#include "libsys.h"
#include <stdio.h>
#include <string.h>
int main(int argc,char **argv){char b[4096],q[128];if(argc==2&&!strcmp(argv[1],"--version")){puts("mintoshctl 0.1.0");return 0;}if(argc==2&&(!strcmp(argv[1],"status")||!strcmp(argv[1],"version"))){if(ms_send_command(MINTOSH_MOSF_SOCKET,!strcmp(argv[1],"status")?"STATUS":"VERSION",b,sizeof b)<0){perror("mintoshctl: MOSF");return 1;}fputs(b,stdout);return 0;}if(argc==2&&!strcmp(argv[1],"services")){if(ms_send_command(MINTOSH_LAUNCH_SOCKET,"LIST",b,sizeof b)<0){perror("mintoshctl: launch7762");return 1;}fputs(b,stdout);return 0;}if(argc==3&&(!strcmp(argv[1],"start")||!strcmp(argv[1],"stop")||!strcmp(argv[1],"restart"))){snprintf(q,sizeof q,"%s %s",!strcmp(argv[1],"start")?"START":!strcmp(argv[1],"stop")?"STOP":"RESTART",argv[2]);if(ms_send_command(MINTOSH_LAUNCH_SOCKET,q,b,sizeof b)<0){perror("mintoshctl: launch7762");return 1;}fputs(b,stdout);return strncmp(b,"OK",2)!=0;}fprintf(stderr,"usage: mintoshctl status|version|services|start NAME|stop NAME|restart NAME\n");return 64;}
